SINA_SMART["pharma-trials"] = {"lecture":"pharma-trials","title":"Clinical trials and new drug development","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"pharma-trials:e0","text":"Development costs $150 million to billions; only 10-15% of approved drugs are real advances.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e1","text":"Zero-order drugs: phenytoin, ethanol, aspirin (PEA).","topic":"Kinetics recap","sec":1,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e2","text":"t½ = 0.693 × Vd / CL; 4-5 half-lives eliminate ~97%.","topic":"Kinetics recap","sec":1,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e3","text":"Alkaline diuresis: salicylate and phenobarbital.","topic":"Kinetics recap","sec":1,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e4","text":"Preclinical screens include CYP450 effects and hERG cardiac safety.","topic":"Discovery and preclinical steps","sec":2,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e10","text":"Crossover: each subject gets all treatments; parallel: separate groups.","topic":"Trial design and phases","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e5","text":"Placebo response up to 30-40%.","topic":"Trial design and phases","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e6","text":"Phase 1: 20-100 healthy volunteers, safety and dose, PK.","topic":"Trial design and phases","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e7","text":"Phase 2: 100-300 patients, proof of concept; only 25% pass.","topic":"Trial design and phases","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e8","text":"Phase 3: hundreds-thousands, double-blind vs standard.","topic":"Trial design and phases","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e9","text":"Phase 4: post-marketing; 1/10,000 toxicities need huge exposure.","topic":"Trial design and phases","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e11","text":"Placental transfer: lipophilic, unbound, < 500 Da drugs cross best.","topic":"Drugs in pregnancy","sec":4,"importance":"core","highYield":"untested"},{"id":"pharma-trials:e12","text":"Thalidomide window: days 34-50; phocomelia.","topic":"Drugs in pregnancy","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"txwknm":"a","e1w5bt":"a","15r3myh":"a","27sy2r":"a","1yxxuxp":"a","k99zmx":"a","1uch4kt":"a","jvllln":"a","pn8s5b":"a","yceucl":"a","1yiillt":"a","9k3ws7":"a","1bziiu0":"a","1y70fry":"a","54ezjc":"a","1ctc9nu":"a","191ra00":"a","1621lzy":"x"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"pharma-trials:e0":{"s":0,"u":["Development costs $150 million to billions; only 10-15% of approved drugs are real advances.","Development costs $150 million to several billion ; thousands of compounds are tested and optimised; only 10-15% of approved drugs are real advances; a patent gives about 10 years of exclusivity before generics (the lecture cites Lipitor sales over $12 billion in 2007)."],"dp":[]},"pharma-trials:e1":{"s":1,"u":["Zero-order drugs: phenytoin, ethanol, aspirin (PEA).","Zero-order : a constant amount eliminated per unit time once enzymes or transporters are saturated; plasma level falls linearly; examples phenytoin, ethanol, aspirin (PEA) at high doses. t½ = 0.693 × Vd / CL : rises with larger Vd or lower clearance; 4-5 half-lives eliminate about 97% (50, 75, 87.5, 93.75, 96.9%); doubling the dose extends action by about one half-life."],"dp":[]},"pharma-trials:e2":{"s":1,"u":["t½ = 0.693 × Vd / CL; 4-5 half-lives eliminate ~97%.","Zero-order : a constant amount eliminated per unit time once enzymes or transporters are saturated; plasma level falls linearly; examples phenytoin, ethanol, aspirin (PEA) at high doses. t½ = 0.693 × Vd / CL : rises with larger Vd or lower clearance; 4-5 half-lives eliminate about 97% (50, 75, 87.5, 93.75, 96.9%); doubling the dose extends action by about one half-life."],"dp":[]},"pharma-trials:e3":{"s":1,"u":["Alkaline diuresis: salicylate and phenobarbital.","Ion trapping : alkalinising urine with sodium bicarbonate keeps salicylate (pKa 3) ionised: ionised/unionised = 10^(pH-pKa), 100:1 at pH 5 but 100,000:1 at pH 8 (10⁵; the slide writes 10,000:1); forced alkaline diuresis is used essentially for salicylate and phenobarbital overdose."],"dp":[]},"pharma-trials:e4":{"s":2,"u":["Preclinical screens include CYP450 effects and hERG cardiac safety.","Screening checks the target, agonist vs antagonist action, off-target effects , effects on CYP450 , and hERG and other cardiac channels (to avoid fatal arrhythmias), then animal disease models."],"dp":[]},"pharma-trials:e10":{"s":3,"u":["Crossover: each subject gets all treatments; parallel: separate groups.","Designs must account for variable disease course ( crossover design : each subject alternates test drug, placebo and standard treatment; parallel design : separate groups), comorbidities, genetics, age, sex, pregnancy, recreational drug use, and randomisation ."],"dp":[]},"pharma-trials:e5":{"s":3,"u":["Placebo response up to 30-40%.","The placebo response (an inert look-alike) can reach 30-40% , with even 'adverse effects'; hence blinding."],"dp":[{"h":"Why a placebo arm is needed","t":"Patients often improve simply from being cared for and expecting benefit, and many diseases fluctuate on their own. Without a blinded placebo comparison, a drug could look effective when it adds nothing. The lecture's figure of a 30-40% placebo response shows how large this effect can be. Source: the lecture's subject and observer bias slide."}]},"pharma-trials:e6":{"s":3,"u":["Phase 1: 20-100 healthy volunteers, safety and dose, PK.","Phase 1 : first in humans, usually healthy volunteers (not for AIDS or cancer drugs); safety and ideal dose by gradual escalation; PK (absorption, half-life, metabolism); open or blinded; 20-100 subjects , months to a year, in specialised centres."],"dp":[{"h":"Why phase 2 is where most drugs fail","t":"Phase 1 asks whether a drug is tolerated; phase 2 asks for the first time whether it actually helps patients with the disease. Many molecules that hit their target beautifully in cells and animals turn out not to change the disease in people, or only at doses that are not tolerated. That is why only about a quarter of drugs survive this phase. Source: the lecture's phase 2 slide."}]},"pharma-trials:e7":{"s":3,"u":["Phase 2: 100-300 patients, proof of concept; only 25% pass.","Phase 2 : proof of concept in 100-300 patients , months to 2 years, often single-blind with placebo and a positive control; highest failure rate: only 25% proceed ."],"dp":[]},"pharma-trials:e8":{"s":3,"u":["Phase 3: hundreds-thousands, double-blind vs standard.","Phase 3 : hundreds to thousands of patients in many countries, compared with the standard treatment, usually double-blind .","Phase 4 : post-approval surveillance for years; several hundred thousand exposures may be needed to see a 1-in-10,000 toxicity."],"dp":[]},"pharma-trials:e9":{"s":3,"u":["Phase 4: post-marketing; 1/10,000 toxicities need huge exposure.","Phase 4 : post-approval surveillance for years; several hundred thousand exposures may be needed to see a 1-in-10,000 toxicity."],"dp":[]},"pharma-trials:e11":{"s":4,"u":["Placental transfer: lipophilic, unbound, < 500 Da drugs cross best.","Placental transfer increases with lipophilicity , low protein binding (though chronic dosing lets bound drugs cross), low molecular weight (cross well under 400-500 Da, rarely above 1,000), and ion trapping (fetal pH slightly lower)."],"dp":[]},"pharma-trials:e12":{"s":4,"u":["Thalidomide window: days 34-50; phocomelia.","Thalidomide : critical window days 34-50 after the last period; 20-30% of exposed children had limb defects (phocomelia), plus ear and visceral anomalies; about 10,000 children affected; probably by inhibiting angiogenesis."],"dp":[]}},"meta":{"txwknm":{"a":"relationship","vg":"pharma-trials:e1/relationship/1"},"e1w5bt":{"a":"relationship","vg":"pharma-trials:e1/relationship/2"},"15r3myh":{"a":"recall","vg":"pharma-trials:e2/recall/1"},"27sy2r":{"a":"recall","vg":"pharma-trials:e2/recall/2"},"1yxxuxp":{"a":"recall","vg":"pharma-trials:e3/recall/1"},"k99zmx":{"a":"recall","vg":"pharma-trials:e3/recall/2"},"1uch4kt":{"a":"relationship","vg":"pharma-trials:e4/relationship/1"},"jvllln":{"a":"recall","vg":"pharma-trials:e5/recall/1"},"pn8s5b":{"a":"recall","vg":"pharma-trials:e6/recall/1"},"yceucl":{"a":"recall","vg":"pharma-trials:e6/recall/2"},"1yiillt":{"a":"recall","vg":"pharma-trials:e7/recall/1"},"9k3ws7":{"a":"recall","vg":"pharma-trials:e8/recall/1"},"1bziiu0":{"a":"recall","vg":"pharma-trials:e9/recall/1"},"1y70fry":{"a":"recall","vg":"pharma-trials:e10/recall/1"},"54ezjc":{"a":"relationship","vg":"pharma-trials:e2/relationship/1"},"1ctc9nu":{"a":"recall","vg":"pharma-trials:e11/recall/1"},"191ra00":{"a":"recall","vg":"pharma-trials:e12/recall/1"}},"explRev":"e98b56e51e5c"};
